import {
  AgentSummaryListQuery,
  AgentSummaryListQuery$data,
  AgentSummaryListQuery$variables,
} from '../__generated__/AgentSummaryListQuery.graphql';
import {
  convertToBinaryUnit,
  toFixedFloorWithoutTrailingZeros,
} from '../helper';
import { ResourceSlotName, useResourceSlotsDetails } from '../hooks/backendai';
import { useBAIPaginationOptionStateOnSearchParam } from '../hooks/reactPaginationQueryOptions';
import { useBAISettingUserState } from '../hooks/useBAISetting';
import { useResourceGroupsForCurrentProject } from '../hooks/useCurrentProject';
import { useHiddenColumnKeysSetting } from '../hooks/useHiddenColumnKeysSetting';
import TableColumnsSettingModal from './TableColumnsSettingModal';
import { IconButton } from '@lablup/ui-common/IconButton';
import { Text } from '@lablup/ui-common/Text';
import { useTheme } from '@lablup/ui-common/theme';
import {
  BAIFlex,
  BAIProgressWithLabel,
  BAIPropertyFilter,
  BAISegmentedControl,
  BAISegmentedControlItem,
  BAITable,
  INITIAL_FETCH_KEY,
  ResourceTypeIcon,
  filterOutNullAndUndefined,
  mergeFilterValues,
  useFetchKey,
  useToggle,
  type BAIColumnType,
  type BAIColumnsType,
  type BAITableProps,
} from 'backend.ai-ui';
import * as _ from 'lodash-es';
import { CircleCheck, CircleMinus, RotateCw } from 'lucide-react';
import { parseAsString, useQueryStates } from 'nuqs';
import React, { useDeferredValue, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { graphql, useLazyLoadQuery } from 'react-relay';

type AgentSummary = NonNullable<
  NonNullable<AgentSummaryListQuery$data['agent_summary_list']>['items'][number]
>;

interface AgentSummaryListProps {
  containerStyle?: React.CSSProperties;
  // Typed against the table's own forwarding type — since ticket 30-D that is
  // the Astryx engine's props, so no antd declaration is reached.
  tableProps?: Partial<Omit<BAITableProps<AgentSummary>, 'dataSource'>>;
}

const AgentSummaryList: React.FC<AgentSummaryListProps> = ({
  containerStyle,
  tableProps,
}) => {
  'use memo';
  const { t } = useTranslation();
  const { token } = useTheme();
  const { mergedResourceSlots } = useResourceSlotsDetails();
  const [visibleColumnSettingModal, { toggle: toggleColumnSettingModal }] =
    useToggle();

  const {
    baiPaginationOption,
    tablePaginationOption,
    setTablePaginationOption,
  } = useBAIPaginationOptionStateOnSearchParam({
    current: 1,
    pageSize: 20,
  });

  const [queryParams, setQuery] = useQueryStates(
    {
      order: parseAsString,
      filter: parseAsString,
      status: parseAsString.withDefault('ALIVE'),
    },
    { history: 'replace' },
  );

  const [fetchKey, updateFetchKey] = useFetchKey();
  const { sftpResourceGroups } = useResourceGroupsForCurrentProject();

  const sftpExclusionFilter =
    sftpResourceGroups && sftpResourceGroups.length > 0
      ? `!(scaling_group in [${sftpResourceGroups.map((group) => `"${group}"`).join(', ')}])`
      : undefined;

  const queryVariables: AgentSummaryListQuery$variables = useMemo(
    () => ({
      limit: baiPaginationOption.limit,
      offset: baiPaginationOption.offset,
      filter: mergeFilterValues([queryParams.filter, sftpExclusionFilter]),
      order: queryParams.order,
      status: queryParams.status,
    }),
    [
      baiPaginationOption.limit,
      baiPaginationOption.offset,
      queryParams.filter,
      queryParams.order,
      queryParams.status,
      sftpExclusionFilter,
    ],
  );
  const deferredQueryVariables = useDeferredValue(queryVariables);
  const deferredFetchKey = useDeferredValue(fetchKey);

  const [columnOverrides, setColumnOverrides] = useBAISettingUserState(
    'table_column_overrides.AgentSummaryList',
  );

  const { agent_summary_list } = useLazyLoadQuery<AgentSummaryListQuery>(
    graphql`
      query AgentSummaryListQuery(
        $limit: Int!
        $offset: Int!
        $filter: String
        $status: String
        $order: String
      ) {
        agent_summary_list(
          limit: $limit
          offset: $offset
          filter: $filter
          status: $status
          order: $order
        ) {
          items {
            id
            status
            architecture
            available_slots
            occupied_slots
            scaling_group
            schedulable
          }
          total_count
        }
      }
    `,
    deferredQueryVariables,
    {
      fetchKey: deferredFetchKey,
      fetchPolicy:
        deferredFetchKey === INITIAL_FETCH_KEY
          ? 'store-and-network'
          : 'network-only',
    },
  );

  const columns: BAIColumnsType<AgentSummary> = [
    {
      title: <>ID</>,
      key: 'id',
      dataIndex: 'id',
      fixed: 'left',
      render: (value) => {
        return (
          <BAIFlex direction="column" align="start">
            <Text>{value}</Text>
          </BAIFlex>
        );
      },
      sorter: true,
    },
    {
      title: t('agent.Architecture'),
      key: 'architecture',
      dataIndex: 'architecture',
    },
    {
      title: t('agent.Allocation'),
      key: 'allocation',
      render: (_value, record) => {
        const parsedOccupiedSlots: {
          [key in ResourceSlotName]: string | undefined;
        } = JSON.parse(record?.occupied_slots || '{}');
        const parsedAvailableSlots: {
          [key in ResourceSlotName]: string | undefined;
        } = JSON.parse(record?.available_slots || '{}');
        return (
          <BAIFlex direction="column" gap="xxs">
            {_.map(
              parsedAvailableSlots,
              (_value: string | number, key: ResourceSlotName) => {
                if (key === 'cpu') {
                  const cpuPercent = _.toFinite(
                    (_.toNumber(parsedOccupiedSlots.cpu) /
                      _.toNumber(parsedAvailableSlots.cpu)) *
                      100,
                  );
                  return (
                    <BAIFlex
                      key={key}
                      justify="between"
                      style={{ minWidth: 220 }}
                    >
                      <BAIFlex gap="xxs">
                        <ResourceTypeIcon key={key} type={key} />
                        <Text>
                          {toFixedFloorWithoutTrailingZeros(
                            parsedOccupiedSlots.cpu || 0,
                            0,
                          )}
                          /
                          {toFixedFloorWithoutTrailingZeros(
                            parsedAvailableSlots.cpu || 0,
                            0,
                          )}
                        </Text>
                        <Text color="secondary" size="2xs">
                          {mergedResourceSlots?.cpu?.display_unit}
                        </Text>
                      </BAIFlex>
                      <BAIProgressWithLabel
                        percent={cpuPercent}
                        strokeColor={
                          cpuPercent > 80
                            ? token('--color-error')
                            : token('--color-success')
                        }
                        width={120}
                        valueLabel={
                          toFixedFloorWithoutTrailingZeros(cpuPercent, 1) + ' %'
                        }
                      />
                    </BAIFlex>
                  );
                } else if (key === 'mem') {
                  const memPercent = _.toFinite(
                    (_.toNumber(parsedOccupiedSlots.mem) /
                      _.toNumber(parsedAvailableSlots.mem)) *
                      100,
                  );
                  return (
                    <BAIFlex
                      key={'mem'}
                      justify="between"
                      style={{ minWidth: 220 }}
                    >
                      <BAIFlex gap="xxs">
                        <ResourceTypeIcon type={'mem'} />
                        <Text>
                          {convertToBinaryUnit(parsedOccupiedSlots.mem, 'g', 0)
                            ?.numberFixed ?? 0}
                          /
                          {convertToBinaryUnit(parsedAvailableSlots.mem, 'g', 0)
                            ?.numberFixed ?? 0}
                        </Text>
                        <Text color="secondary" size="2xs">
                          GiB
                        </Text>
                      </BAIFlex>
                      <BAIProgressWithLabel
                        percent={memPercent}
                        strokeColor={
                          memPercent > 80
                            ? token('--color-error')
                            : token('--color-success')
                        }
                        width={120}
                        valueLabel={
                          toFixedFloorWithoutTrailingZeros(memPercent, 1) + ' %'
                        }
                      />
                    </BAIFlex>
                  );
                } else if (parsedAvailableSlots[key]) {
                  const percent = _.toFinite(
                    (_.toNumber(parsedOccupiedSlots[key]) /
                      _.toNumber(parsedAvailableSlots[key])) *
                      100,
                  );
                  return (
                    <BAIFlex
                      key={key}
                      justify="between"
                      style={{ minWidth: 220 }}
                      gap="xxs"
                    >
                      <BAIFlex gap="xxs">
                        <ResourceTypeIcon key={key} type={key} />
                        <Text>
                          {toFixedFloorWithoutTrailingZeros(
                            parsedOccupiedSlots[key] || 0,
                            2,
                          )}
                          /
                          {toFixedFloorWithoutTrailingZeros(
                            parsedAvailableSlots[key],
                            2,
                          )}
                        </Text>
                        <Text color="secondary" size="2xs">
                          {mergedResourceSlots?.[key]?.display_unit}
                        </Text>
                      </BAIFlex>
                      <BAIProgressWithLabel
                        percent={percent}
                        strokeColor={
                          percent > 80
                            ? token('--color-error')
                            : token('--color-success')
                        }
                        width={120}
                        valueLabel={
                          toFixedFloorWithoutTrailingZeros(percent, 1) + ' %'
                        }
                      />
                    </BAIFlex>
                  );
                }
              },
            )}
          </BAIFlex>
        );
      },
    },
    {
      title: t('general.ResourceGroup'),
      key: 'scaling_group',
      dataIndex: 'scaling_group',
      sorter: true,
    },
    {
      title: t('agent.Schedulable'),
      key: 'schedulable',
      dataIndex: 'schedulable',
      render: (value) => {
        return (
          <BAIFlex justify="center">
            {value === true ? (
              <CircleCheck
                style={{
                  color: token('--color-success'),
                  fontSize: token('--font-size-xl'),
                }}
                size="1em"
              />
            ) : (
              <CircleMinus
                style={{
                  color: token('--color-text-disabled'),
                  fontSize: token('--font-size-xl'),
                }}
                size="1em"
              />
            )}
          </BAIFlex>
        );
      },
      sorter: true,
    },
  ];
  const [hiddenColumnKeys, setHiddenColumnKeys] =
    useHiddenColumnKeysSetting('AgentSummaryList');

  return (
    <BAIFlex direction="column" align="stretch" style={containerStyle} gap="sm">
      <BAIFlex justify="between" align="start" gap="xs" wrap="wrap">
        <BAIFlex
          direction="row"
          gap={'sm'}
          align="start"
          style={{ flex: 1 }}
          wrap="wrap"
        >
          <BAISegmentedControl
            value={queryParams.status}
            onChange={(value) => {
              setQuery({ status: value });
            }}
          >
            <BAISegmentedControlItem
              value="ALIVE"
              label={t('agent.Connected')}
            />
            <BAISegmentedControlItem
              value="TERMINATED"
              label={t('agent.Terminated')}
            />
          </BAISegmentedControl>

          <BAIPropertyFilter
            filterProperties={[
              {
                key: 'id',
                propertyLabel: 'ID',
                type: 'string',
              },
              {
                key: 'schedulable',
                propertyLabel: t('agent.Schedulable'),
                type: 'boolean',
                options: [
                  {
                    label: t('general.Enabled'),
                    value: 'true',
                  },
                  {
                    label: t('general.Disabled'),
                    value: 'false',
                  },
                ],
              },
            ]}
            value={queryParams.filter ?? undefined}
            onChange={(value) => {
              setQuery({ filter: value ?? null });
              setTablePaginationOption({ current: 1 });
            }}
          />
        </BAIFlex>
        <BAIFlex gap="xs">
          <IconButton
            label={t('button.Refresh')}
            tooltip={t('button.Refresh')}
            isLoading={deferredFetchKey !== fetchKey}
            onClick={() => updateFetchKey()}
            icon={<RotateCw size="1em" />}
          />
        </BAIFlex>
      </BAIFlex>
      <BAITable
        scroll={{ x: 'max-content' }}
        bordered
        rowKey={'id'}
        dataSource={filterOutNullAndUndefined(agent_summary_list?.items)}
        columns={
          _.filter(
            columns,
            (column) => !_.includes(hiddenColumnKeys, _.toString(column?.key)),
          ) as BAIColumnType<AgentSummary>[]
        }
        pagination={{
          pageSize: tablePaginationOption.pageSize,
          current: tablePaginationOption.current,
          total: agent_summary_list?.total_count ?? 0,
          onChange(current, pageSize) {
            if (_.isNumber(current) && _.isNumber(pageSize)) {
              setTablePaginationOption({ current, pageSize });
            }
          },
        }}
        order={queryParams.order}
        onChangeOrder={(order) => {
          setQuery({ order: order ?? null });
        }}
        tableSettings={{
          columnOverrides: columnOverrides,
          onColumnOverridesChange: setColumnOverrides,
        }}
        loading={deferredQueryVariables !== queryVariables}
        {...tableProps}
      />
      <TableColumnsSettingModal
        open={visibleColumnSettingModal}
        onRequestClose={(values) => {
          values?.selectedColumnKeys &&
            setHiddenColumnKeys(
              _.difference(
                columns.map((column) => _.toString(column.key)),
                values?.selectedColumnKeys,
              ),
            );
          toggleColumnSettingModal();
        }}
        columns={columns}
        hiddenColumnKeys={hiddenColumnKeys}
      />
    </BAIFlex>
  );
};

export default AgentSummaryList;
